// --- UI CONFIGURATION ---
// We use u from -1 to 1 to represent the two halves (Below -> Above)
u_min := -1.0; 
u_max := 1.0; 
v_min := -3.14159;
v_max := 3.14159;
steps := 300;  // High quality for the junction
A := 10.0;     // k
B := 0.1;      // SCALE
C := 0.0;     

// --- BEGIN GLSL ---

// FIX: Use A and B directly, which are the exact names generated by the engine
float k = A;       
float scale = B;   

// 1. SMART RADIUS MAPPING
// Skip the central part and join the inner edges.
float u_input = u;
float u_real = 0.28 + abs(u_input) * (1.09 - 0.28);

// 2. Base geometry computation
float v_val = v; 

float pow_u_2k_1 = pow(u_real, 2.0 * k - 1.0);
float pow_u_k    = pow(u_real, k);

float x = k * u_real * cos(v_val) - (pow_u_2k_1 / 6.0) * cos((2.0 * k - 1.0) * v_val);
float y = -k * u_real * sin(v_val) - (pow_u_2k_1 / 6.0) * sin((2.0 * k - 1.0) * v_val);
float z_base = -(pow_u_k * cos(k * v_val));

// 3. FACE SELECTION (Above or Below)
float shift = 2.0 * exp(2.0 * cos(4.0 * u_real));
float constant = 24.0 / 5.0; // 4.8
float finalZ;

if (u_input < 0.0) {
    // Component 1 (Below)
    finalZ = z_base - shift + constant;
} else {
    // Component 2 (Above)
    finalZ = -z_base + shift - constant;
}

// 4. Output
return vec4(x * scale, y * scale, finalZ * scale, 0.0);
